export const ADVISORIES_CHECKED = '2026-11-08';

export type AdvisoryLevel = 'block' | 'warn' | 'info';

export type Advisory = {
  id: string;
  /** Library name as the scan stores it (Maven group:artifact, framework name, openssl, zlib). */
  lib: string;
  label: string;
  cve: string;
  url: string;
  year: number;
  /** Plain words for the affected range, shown in the finding. */
  range: string;
  level: AdvisoryLevel;
  affected: (version: string) => boolean;
  detail: string;
  fix: string;
};

type V = (number | string)[];

/** "1.0.1g" -> [1, 0, 1, "g"], "4.9.2" -> [4, 9, 2]; null when it is not a plain version. */
export function parseVersion(v: string): V | null {
  const m = /^(\d+(?:\.\d+){0,3})([a-z]{0,2})(?:[-+ ].*)?$/.exec(v.trim());
  if (!m) return null;
  const out: V = m[1].split('.').map(Number);
  if (m[2]) out.push(m[2]);
  return out;
}

/** Compares two versions part by part; letter suffixes (OpenSSL) sort by length, then alphabetically ("z" < "za"). */
export function compareVersions(a: string, b: string): number {
  const x = parseVersion(a);
  const y = parseVersion(b);
  if (!x || !y) return NaN;
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    const p = x[i] ?? (typeof y[i] === 'string' ? '' : 0);
    const q = y[i] ?? (typeof x[i] === 'string' ? '' : 0);
    if (typeof p === 'number' && typeof q === 'number') {
      if (p !== q) return p < q ? -1 : 1;
    } else {
      const ps = String(p);
      const qs = String(q);
      if (ps.length !== qs.length) return ps.length < qs.length ? -1 : 1;
      if (ps !== qs) return ps < qs ? -1 : 1;
    }
  }
  return 0;
}

const lt = (v: string, b: string) => compareVersions(v, b) < 0;
const gte = (v: string, b: string) => compareVersions(v, b) >= 0;
/** Same OpenSSL series ("1.0.1" of "1.0.1g"). */
const series = (v: string) => /^(\d+\.\d+\.\d+)/.exec(v)?.[1] ?? '';

