/** Advisories that match the library versions read from a build, with the version found. */
export function matchAdvisories(libs: { name: string; version: string }[]): { advisory: Advisory; version: string }[] {
  const out: { advisory: Advisory; version: string }[] = [];
  for (const a of ADVISORIES) {
    const hit = libs.find((l) => l.name.toLowerCase() === a.lib.toLowerCase() && parseVersion(l.version) && a.affected(l.version));
    if (hit) out.push({ advisory: a, version: hit.version });
  }
  return out;
}
